#!/bin/bash
D=$(mktemp -d); google-chrome --user-data-dir=$D --headless=new --no-sandbox --use-angle=swiftshader --virtual-time-budget=600000 --dump-dom "http://localhost:8765/tools/body_v4/${2:-analyze.html}?$1&cb=$RANDOM" 2>/dev/null | python3 -c "import sys,html,re;s=sys.stdin.read();m=re.search(r'<pre id=\"o\">(.*?)</pre>',s,re.S);print(html.unescape(m.group(1)) if m else s[:2000])"; rm -rf $D
